#include "Recording.h"
#include "ThirdParty/json.hpp"
#include <iomanip>
#include <limits>
#include <sstream>
#include <stdexcept>
namespace Replay {
namespace {
using Json=nlohmann::json;
void Require(bool ok,const char* text){if(!ok)throw std::invalid_argument(text);}
const char* Type(Kind kind){return kind==Kind::Keyboard?"keyboard":"mouse";}
void Keys(const Json& j,std::initializer_list<const char*> names){Require(j.is_object(),"Expected a JSON object.");for(auto i=j.begin();i!=j.end();++i){bool found=false;for(auto name:names)if(i.key()==name)found=true;Require(found,"Unknown recording property.");}}
std::int64_t Number(const Json& j,std::int64_t minimum,std::int64_t maximum){Require(j.is_number_integer(),"Expected an integer.");if(j.is_number_unsigned())Require(j.get<std::uint64_t>()<=static_cast<std::uint64_t>(maximum),"Integer exceeds the supported limit.");const auto n=j.get<std::int64_t>();Require(n>=minimum&&n<=maximum,"Integer is outside its supported range.");return n;}
}
void Validate(const Recording& r){Require(!r.name.empty()&&r.name.size()<=120,"Recording name must contain 1..120 UTF-8 bytes.");for(unsigned char c:r.name)Require(c>=32,"Recording name contains a control character.");Require(r.events.size()<=100000,"A recording is limited to 100000 events.");std::uint64_t before=0;for(const auto& e:r.events){Require(e.kind==r.kind,"A recording must contain exactly one device family.");Require(e.at_us>=before&&e.at_us<=3600000000ULL,"Event times must increase and stay within one hour.");before=e.at_us;if(e.kind==Kind::Keyboard){Require(e.code>0&&e.code<=0xFF&&!(e.flags&~7u),"Invalid keyboard scan code or flags.");Require(!e.buttons&&!e.data&&!e.x&&!e.y,"Keyboard event contains mouse fields.");}else{Require(!(e.flags&~15u)&&!(e.buttons&~0x1FFFu),"Invalid mouse flags.");Require(!e.code,"Mouse event contains a keyboard scan code.");}}}
Recording Parse(std::string_view text){Require(text.size()<=32*1024*1024,"Recording JSON exceeds 32 MiB.");unsigned depth=0;std::vector<std::set<std::string>> keys;const auto callback=[&](int,Json::parse_event_t event,Json& value){if(event==Json::parse_event_t::object_start||event==Json::parse_event_t::array_start){Require(++depth<=16,"JSON nesting is too deep.");if(event==Json::parse_event_t::object_start)keys.emplace_back();}else if(event==Json::parse_event_t::object_end||event==Json::parse_event_t::array_end){--depth;if(event==Json::parse_event_t::object_end)keys.pop_back();}else if(event==Json::parse_event_t::key)Require(!keys.empty()&&keys.back().insert(value.get<std::string>()).second,"Duplicate JSON properties are not allowed.");return true;};const auto j=Json::parse(text.begin(),text.end(),callback);Keys(j,{"schema","name","type","events"});Require(Number(j.at("schema"),1,1)==1,"Unsupported recording schema.");Require(j.at("name").is_string()&&j.at("type").is_string(),"Recording name/type must be strings.");Recording r;r.name=j.at("name").get<std::string>();const auto type=j.at("type").get<std::string>();Require(type=="keyboard"||type=="mouse","Recording type must be keyboard or mouse.");r.kind=type=="keyboard"?Kind::Keyboard:Kind::Mouse;const auto& events=j.at("events");Require(events.is_array()&&events.size()<=100000,"events must be an array of at most 100000 records.");r.events.reserve(events.size());for(const auto& event:events){Keys(event,{"at_us","code","flags","buttons","data","x","y"});Event e;e.kind=r.kind;e.at_us=static_cast<std::uint64_t>(Number(event.at("at_us"),0,3600000000LL));e.code=static_cast<std::uint16_t>(Number(event.at("code"),0,65535));e.flags=static_cast<std::uint16_t>(Number(event.at("flags"),0,65535));e.buttons=static_cast<std::uint16_t>(Number(event.at("buttons"),0,65535));e.data=static_cast<std::uint16_t>(Number(event.at("data"),0,65535));e.x=static_cast<std::int32_t>(Number(event.at("x"),INT32_MIN,INT32_MAX));e.y=static_cast<std::int32_t>(Number(event.at("y"),INT32_MIN,INT32_MAX));r.events.push_back(e);}Validate(r);return r;}
std::string Serialize(const Recording& r){Validate(r);Json j={{"schema",1},{"name",r.name},{"type",Type(r.kind)},{"events",Json::array()}};for(const auto& e:r.events)j["events"].push_back({{"at_us",e.at_us},{"code",e.code},{"flags",e.flags},{"buttons",e.buttons},{"data",e.data},{"x",e.x},{"y",e.y}});return j.dump(2)+"\n";}
std::string Csv(const Recording& r){Validate(r);std::ostringstream out;out<<"at_us,type,code,flags,buttons,data,x,y\n";for(const auto& e:r.events)out<<e.at_us<<','<<Type(e.kind)<<','<<e.code<<','<<e.flags<<','<<e.buttons<<','<<e.data<<','<<e.x<<','<<e.y<<'\n';return out.str();}
std::string Describe(const Event& e){std::ostringstream out;out<<std::fixed<<std::setprecision(3)<<double(e.at_us)/1000<<" ms   ";if(e.kind==Kind::Keyboard)out<<"scan "<<e.code<<((e.flags&1)?" UP":" DOWN")<<" flags "<<e.flags;else out<<"X "<<e.x<<"  Y "<<e.y<<"  buttons "<<e.buttons<<"  data "<<e.data;return out.str();}
void Held::Accept(const Event& e){if(e.kind==Kind::Keyboard){const auto key=std::uint32_t(e.code)|(std::uint32_t(e.flags&6u)<<16);if(e.flags&1)keys_.erase(key);else keys_.insert(key);}else{for(unsigned i=0;i<5;++i){const auto down=static_cast<std::uint16_t>(1u<<(i*2));const auto up=static_cast<std::uint16_t>(down<<1);if(e.buttons&down)buttons_|=static_cast<std::uint16_t>(1u<<i);if(e.buttons&up)buttons_&=static_cast<std::uint16_t>(~(1u<<i));}}}
std::vector<Event> Held::Release(){std::vector<Event> events;for(auto key:keys_){Event e;e.code=static_cast<std::uint16_t>(key);e.flags=static_cast<std::uint16_t>((key>>16)|1);events.push_back(e);}if(buttons_){Event e;e.kind=Kind::Mouse;for(unsigned i=0;i<5;++i)if(buttons_&(1u<<i))e.buttons|=static_cast<std::uint16_t>(2u<<(i*2));events.push_back(e);}keys_.clear();buttons_=0;return events;}
}
